import { burnCollision } from '../orbs/orange-burn.js';import { chargeCollision,dischargeCharge,advanceStun,voltTackle } from '../orbs/yellow-charge.js';import { advanceMagnet,magnetWallCollision } from '../orbs/green-magnet.js';import { advanceWarp,resetWarpCounters } from '../orbs/indigo-warp.js';import { advanceShadow } from '../orbs/purple-shadow.js';import { advanceInversionHold } from '../orbs/inversion.js';
export function advanceEffects(state,physicsEvents,dt,rng,{warpStep=advanceWarp,previousBall=null}={}){const t=state.match.temporary;t.magnet=advanceMagnet(t.magnet,state,dt);warpStep(t.portals,state.ball,dt,rng,previousBall);t.shadows=t.shadows.map(s=>advanceShadow(s,state.width,state.height,dt)).filter(Boolean);for(const side of['player1','player2'])t.stuns[side]=advanceStun(t.stuns[side],dt);t.inversion=advanceInversionHold(t.inversion,dt);
  for(const e of physicsEvents){if(e.type==='paddleHit'||e.type==='score')resetWarpCounters(t.portals,state.ball);let chargeEvent={charge:t.charge,becameLive:false};if(e.type==='wallHit'){t.burn=burnCollision(t.burn,'wall',state.ball);chargeEvent=chargeCollision(t.charge);t.charge=chargeEvent.charge;magnetWallCollision(t.magnet,state)}if(e.type==='paddleHit'){t.burn=burnCollision(t.burn,'paddle',state.ball);chargeEvent=chargeCollision(t.charge);t.charge=chargeEvent.charge;if(t.stuns[e.side]){voltTackle(state.ball,state.paddles[e.side].side);t.stuns[e.side]=null}else if(!chargeEvent.becameLive){const d=dischargeCharge(t.charge,e.side);t.charge=d.charge;if(d.stun)t.stuns[d.stun.side]=d.stun}}}
}
export function isInversionHolding(state){return Boolean(state.match.temporary.inversion)}
